  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2f3a2c;
  background: #fbfaf6;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
  border-bottom: 1px solid #e6e3da;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 22px;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #55604f;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 56px 64px 48px;
}

.hero-text {
  max-width: 520px;
}

h1 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.15;
}

.hero-text p {
  margin: 0 0 24px;
  color: #55604f;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #3d6b35;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.hero-plan {
  width: 420px;
  padding: 20px;
  border: 1px solid #e6e3da;
  border-radius: 8px;
  background: #ffffff;
}

.plan-title {
  margin-bottom: 12px;
  color: #55604f;
}

.plan-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.plot {
  height: 52px;
  padding: 4px 6px;
  border-radius: 4px;
  font-size: 13px;
}

.plot.taken {
  background: #e4e8df;
  color: #55604f;
}

.plot.free {
  background: #3d6b35;
  color: #ffffff;
}

.plan-key {
  margin-top: 12px;
  font-size: 13px;
  color: #55604f;
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin: 0 6px 0 0;
  border-radius: 2px;
}

.swatch.taken {
  margin-left: 16px;
  background: #e4e8df;
}

.swatch.free {
  background: #3d6b35;
}

.features {
  padding: 8px 64px 0;
}

h2 {
  margin: 0 0 12px;
  font-size: 15px;
  font-weight: 400;
  color: #55604f;
}

.cards {
  display: flex;
  gap: 12px;
}

.card {
  flex: 1;
  padding: 14px 16px;
  background: #f1efe8;
}

.card h3 {
  margin: 0;
  font-size: 15px;
  font-weight: 400;
  color: #55604f;
}

.card p {
  margin: 0;
  color: #55604f;
}

