  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

/* Shared measurements: the page side margin, the widest the content gets,
   and the gap between grid columns. The hero and the cards use the same
   four-column grid, so the plot map starts on the edge of the third card. */
:root {
  --side: 64px;
  --content-max: 1152px;
  --gap: 24px;
  --text: #2f3a2c;
  --muted: #55604f;
  --green: #3d6b35;
  --line: #e6e3da;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: var(--text);
  background: #fbfaf6;
}

a {
  color: inherit;
}

/* The header, hero and features each keep their content inside the same
   centered column. max() keeps the side margin when the window is narrow,
   and centers the content when the window is wider than --content-max. */
.site-header,
.hero,
.features {
  padding-left: max(var(--side), calc((100% - var(--content-max)) / 2));
  padding-right: max(var(--side), calc((100% - var(--content-max)) / 2));
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 28px;
  padding-top: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 22px;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0 20px;
}

/* Padding makes each link a tap target at least 24 px tall. */
.site-nav a {
  padding: 6px 0;
  text-decoration: none;
  color: var(--muted);
}

.hero {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  column-gap: var(--gap);
  row-gap: 40px;
  align-items: center;
  padding-top: 64px;
  padding-bottom: 64px;
}

.hero-text {
  grid-column: 1 / span 2;
  max-width: 34em;
}

h1 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.15;
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 24px;
  color: var(--muted);
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: var(--green);
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.hero-plan {
  grid-column: 3 / span 2;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #ffffff;
}

.plan-title {
  margin-bottom: 12px;
  color: var(--muted);
}

.plan-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.plot {
  height: 56px;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 13px;
  line-height: 1.4;
}

.plot.taken {
  background: #e4e8df;
  color: var(--muted);
}

/* Empty plots carry the word "Empty" as well as the green fill,
   so the state does not depend on color alone. */
.plot.free {
  background: var(--green);
  color: #ffffff;
}

.plot span {
  display: block;
  font-weight: 500;
}

.plan-key {
  margin-top: 12px;
  font-size: 13px;
  color: var(--muted);
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin: 0 6px 0 0;
  border-radius: 2px;
}

.swatch.taken {
  margin-left: 16px;
  background: #e4e8df;
}

.swatch.free {
  background: var(--green);
}

.features {
  padding-top: 0;
  padding-bottom: 72px;
}

h2 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 24px;
  font-weight: 400;
  line-height: 1.25;
  color: var(--text);
}

.cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  padding: 16px 18px 18px;
  background: #f1efe8;
}

.card h3 {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 500;
  color: var(--text);
}

/* "pretty" stops a single word from sitting alone on the last line. */
.card p {
  margin: 0;
  color: var(--muted);
  text-wrap: pretty;
}

/* Tablet: the text and the plot map stack, and the cards go two by two. */
@media (max-width: 960px) {
  .hero-text,
  .hero-plan {
    grid-column: 1 / -1;
  }

  .hero-plan {
    max-width: 520px;
  }

  .cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Phone: narrower margins, a smaller headline, one card per row,
   and the plot map in four columns so each plot stays wide enough. */
@media (max-width: 600px) {
  :root {
    --side: 20px;
    --gap: 16px;
  }

  .hero {
    padding-top: 40px;
    padding-bottom: 48px;
  }

  h1 {
    font-size: 32px;
  }

  .plan-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .cards {
    grid-template-columns: 1fr;
  }
}

